def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    for r in range(h - 1):
        for c in range(w - 1):
            if not all(grid[i][j] == 2 for i in (r, r + 1) for j in (c, c + 1)):
                continue

            # A ray starts at each diagonal marker and proceeds away from
            # the 2x2 block. Its color is shifted to the next marker color
            # in the block's four-corner sequence.
            corners = [
                (r - 1, c - 1, -1, -1),
                (r - 1, c + 2, -1, 1),
                (r + 2, c - 1, 1, -1),
                (r + 2, c + 2, 1, 1),
            ]
            vals = []
            for sr, sc, dr, dc in corners:
                vals.append(grid[sr][sc] if 0 <= sr < h and 0 <= sc < w else 0)

            # UL takes LL's color; UR takes UL's; LL takes LR's; LR takes UR's.
            shifted = [vals[2], vals[0], vals[3], vals[1]]
            for (sr, sc, dr, dc), color in zip(corners, shifted):
                if color not in range(1, 10) or not (0 <= sr < h and 0 <= sc < w):
                    continue
                rr, cc = sr, sc
                while 0 <= rr < h and 0 <= cc < w:
                    if grid[rr][cc] != 2:
                        out[rr][cc] = color
                    rr += dr
                    cc += dc

    return out
